    getReactivateBenefit:function(){
        return{
            text: 'Reativar Benefício',
            scope: this,
            iconCls: true,
            icon: '/' + global.Context + '/static/engine/images/icons/athenas-0032.png',
            handler: function () {
                var selected = this.getSelectionModel().getSelected();
                if (selected != undefined){
                    if(selected.get('desligamento') && selected.get('tipo_movcarreira') == 'BENEFICIO' ){
                        var klassDef = 'rh.movimentacao.possession.benefit.reactivated.Window';
                        var rest = Ext._create(klassDef, {
                            action: 'create',
                            modal:true,
                            ownerGrid: this,
                            params: {movimentacao_posse: selected.get('pk')},
                            values: {movimentacao_posse: selected.get('pk')},
                            callback: {
                                success: {
                                    scope: this,
                                    fn: function() {
                                        this.getStore().reload();
                                    }
                                }
                            }
                        });
                        rest.show();
                    }else{
                        var msg = "Benefício ativo não pode ser reativado."
                        if (selected.get('tipo_movcarreira') != "BENEFICIO")
                            msg = "Provimento "+selected.data.tipo_movcarreira+" Não pode ser reativado."
                        alert(msg);
                    }
                }else{
                    alert('Selecione um provimento!');
                }

            }
        }
    },

